// This code has been fully generated by an AI.
//
// Training pages: fitness/fatigue/form with daily load, and time in zones
// per week as stacked bars.

import uPlot from "./vendor/uplot-1.6.32/uPlot.esm.js";
import { axisStyle, withAlpha } from "./theme-data.js";
import { chartColors, onThemeChange } from "./theme.js";
import { stack, labelStep } from "./stats-data.js";

const num = (v, d = 0) => (v == null ? "–" : v.toLocaleString("de-DE", { maximumFractionDigits: d }));
const day = (s) => new Date(s * 1000).toLocaleDateString("de-DE", { day: "numeric", month: "short", year: "2-digit", timeZone: "UTC" });
const compact = (el) => el.clientWidth < 520;

function redrawable(draw) {
  let handle = draw();
  onThemeChange(() => {
    handle.forEach((h) => h.destroy());
    handle = draw();
  });
}

function sized(container, plot, height) {
  const resize = new ResizeObserver(() => plot.setSize({ width: container.clientWidth, height: height() }));
  resize.observe(container);
  return {
    destroy() {
      resize.disconnect();
      plot.destroy();
    },
  };
}

const dateAxis = (colors) =>
  axisStyle(colors, {
    size: 30,
    values: (u, ticks) => ticks.map((t) => new Date(t * 1000).toLocaleDateString("de-DE", { day: "numeric", month: "short", timeZone: "UTC" })),
  });

export function showLoad() {
  const data = JSON.parse(document.getElementById("load-data").textContent);
  const top = document.getElementById("load-fitness");
  const bottom = document.getElementById("load-daily");
  const readout = document.getElementById("load-readout");
  const last = data.days.length - 1;
  const show = (i) => {
    if (i == null) i = last;
    readout.textContent = `${day(data.days[i])}: Fitness ${num(data.fitness[i])} · Ermüdung ${num(data.fatigue[i])} · Form ${num(data.form[i])} · Belastung ${num(data.load[i])}`;
  };
  show(null);

  redrawable(() => {
    const colors = chartColors();
    const sync = uPlot.sync("load");
    const h1 = () => (compact(top) ? 200 : 260);
    const fitness = new uPlot({
      width: top.clientWidth,
      height: h1(),
      legend: { show: false },
      cursor: { sync: { key: sync.key }, drag: { x: false, y: false } },
      scales: { x: { time: true } },
      axes: [dateAxis(colors), axisStyle(colors, { size: 40, values: (u, t) => t.map((v) => num(v)) })],
      series: [
        {},
        { stroke: colors.series.speed, width: 2 },
        { stroke: colors.series.hr, width: 1.5 },
        { stroke: colors.series.cad, width: 1.5, fill: withAlpha(colors.series.cad, 0.12) },
      ],
      hooks: { setCursor: [(u) => show(u.cursor.idx)] },
    }, [data.days, data.fitness, data.fatigue, data.form], top);
    const h2 = () => (compact(bottom) ? 110 : 140);
    const daily = new uPlot({
      width: bottom.clientWidth,
      height: h2(),
      legend: { show: false },
      cursor: { sync: { key: sync.key }, drag: { x: false, y: false }, points: { show: false } },
      scales: { x: { time: true }, y: { range: (u, min, max) => [0, Math.max(10, max * 1.1)] } },
      axes: [dateAxis(colors), axisStyle(colors, { size: 40, values: (u, t) => t.map((v) => num(v)) })],
      series: [{}, { stroke: colors.accent, fill: withAlpha(colors.accent, 0.7), paths: uPlot.paths.bars({ size: [0.8, 12] }), points: { show: false } }],
      hooks: { setCursor: [(u) => show(u.cursor.idx)] },
    }, [data.days, data.load], bottom);
    return [sized(top, fitness, h1), sized(bottom, daily, h2)];
  });
}

export function showZones() {
  const data = JSON.parse(document.getElementById("zones-data").textContent);
  const container = document.getElementById("zones-chart");
  const readout = document.getElementById("zones-readout");
  const x = data.labels.map((_, i) => i);
  const { bands } = stack(data.hours);
  const totals = x.map((i) => data.hours.reduce((a, s) => a + (s[i] ?? 0), 0));
  const show = (i) => {
    if (i == null) {
      readout.textContent = "";
      return;
    }
    const parts = data.zones.map((z, k) => `Z${z} ${num(data.hours[k][i], 1)}`);
    readout.textContent = `${data.labels[i]}: ${num(totals[i], 1)} h · ${parts.join(" · ")}`;
  };
  redrawable(() => {
    const colors = chartColors();
    const css = getComputedStyle(document.documentElement);
    const zoneColor = (z) => css.getPropertyValue(`--zone-${z}`).trim();
    const height = () => (compact(container) ? 220 : 280);
    // Bars are drawn top zone first, each as cumulative sum, so lower zones
    // paint over the upper part of higher ones (classic stacked bars).
    const order = [...data.zones.keys()].reverse();
    const plot = new uPlot({
      width: container.clientWidth,
      height: height(),
      legend: { show: false },
      cursor: { drag: { x: false, y: false }, points: { show: false } },
      scales: { x: { time: false, range: [-0.6, x.length - 0.4] }, y: { range: (u, min, max) => [0, Math.max(1, max * 1.1)] } },
      axes: [
        axisStyle(colors, {
          splits: () => x,
          values: (u, ticks) => {
            const step = labelStep(data.labels.length, u.bbox.width / devicePixelRatio);
            return ticks.map((t) => (t % step === 0 ? data.labels[t] ?? "" : ""));
          },
          grid: { show: false },
          size: 28,
        }),
        axisStyle(colors, { size: 36, values: (u, t) => t.map((v) => num(v, 1)) }),
      ],
      series: [
        {},
        ...order.map((k) => ({
          stroke: zoneColor(data.zones[k]),
          fill: zoneColor(data.zones[k]),
          paths: uPlot.paths.bars({ size: [0.7, 40] }),
          points: { show: false },
        })),
      ],
      hooks: { setCursor: [(u) => show(u.cursor.idx)] },
    }, [x, ...order.map((k) => bands[k])], container);
    return [sized(container, plot, height)];
  });
}
